result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/hpa/grid.py", "content": """"Grid generation and basic search utilities (BFS)."""
from __future__ import annotations

import random
from collections import deque

OPEN = 0
WALL = 1

Cell = tuple[int, int]  # (row, col)


def generate_grid(
    width: int = 32,
    height: int = 32,
    wall_probability: float = 0.25,
    seed: int = 11,
) -> tuple[tuple[int, ...], ...]:
    """Generate a seeded random obstacle grid (0 = open, 1 = wall)."""
    rng = random.Random(seed)
    return tuple(
        tuple(WALL if rng.random() < wall_probability else OPEN for _ in range(width))
        for _ in range(height)
    )


def in_bounds(grid, r: int, c: int) -> bool:
    return 0 <= r < len(grid) and 0 <= c < len(grid[0])


def is_open(grid, r: int, c: int) -> bool:
    return in_bounds(grid, r, c) and grid[r][c] == OPEN


def neighbors4(grid, cell: Cell):
    """Yield the 4-connected open neighbours of *cell*."""
    r, c = cell
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = r + dr, c + dc
        if is_open(grid, nr, nc):
            yield (nr, nc)


def bfs(grid, source: Cell, region=None):
    """BFS from *source* over open cells.

    ``region(cell) -> bool`` optionally restricts the search area.
    Returns ``(dist, parent)`` dicts keyed by cell.
    """
    if region is None:
        region = lambda cell: True  # noqa: E731
    dist = {source: 0}
    parent: dict[Cell, Cell] = {}
    queue = deque([source])
    while queue:
        cur = queue.popleft()
        for nxt in neighbors4(grid, cur):
            if nxt not in dist and region(nxt):
                dist[nxt] = dist[cur] + 1
                parent[nxt] = cur
                queue.append(nxt)
    return dist, parent


def bfs_path(parent: dict[Cell, Cell], source: Cell, target: Cell) -> list[Cell]:
    """Reconstruct a source->target path from a BFS parent map."""
    path = [target]
    while path[-1] != source:
        path.append(parent[path[-1]])
    path.reverse()
    return path


def shortest_path(grid, start: Cell, goal: Cell) -> list[Cell] | None:
    """True BFS shortest path on the full grid, or None if unreachable."""
    if not (is_open(grid, *start) and is_open(grid, *goal)):
        return None
    dist, parent = bfs(grid, start)
    if goal not in dist:
        return None
    return bfs_path(parent, start, goal)


def random_open_cell(rng: random.Random, grid) -> Cell:
    """Pick a uniformly random open cell (rejection sampling)."""
    while True:
        r = rng.randrange(len(grid))
        c = rng.randrange(len(grid[0]))
        if grid[r][c] == OPEN:
            return (r, c)
