from __future__ import annotations

from dataclasses import dataclass

from .grid import is_open


@dataclass(frozen=True)
class Cluster:
    """A rectangular cluster of cells; bounds are half-open [row0,row1) x [col0,col1)."""

    id: int
    row0: int
    col0: int
    row1: int
    col1: int

    @property
    def rows(self):
        return range(self.row0, self.row1)

    @property
    def cols(self):
        return range(self.col0, self.col1)

    def contains(self, r: int, c: int) -> bool:
        return self.row0 <= r < self.row1 and self.col0 <= c < self.col1


@dataclass(frozen=True)
class Entrance:
    """An open crossing between two adjacent clusters.

    ``cell_a`` lies inside cluster ``a`` and ``cell_b`` inside cluster ``b``
    and the two cells are 4-adjacent across the shared border.
    """

    a: Cluster
    b: Cluster
    cell_a: tuple[int, int]
    cell_b: tuple[int, int]


def partition(grid, cluster_size: int = 8):
    """Split the grid into ``cluster_size x cluster_size`` blocks.

    Returns ``(clusters, index)`` where ``index[(block_row, block_col)]`` maps
    to the corresponding :class:`Cluster`.
    """
    height, width = len(grid), len(grid[0])
    clusters: list[Cluster] = []
    index: dict[tuple[int, int], Cluster] = {}
    cid = 0
    for br, top in enumerate(range(0, height, cluster_size)):
        for bc, left in enumerate(range(0, width, cluster_size)):
            cluster = Cluster(
                id=cid,
                row0=top,
                col0=left,
                row1=min(top + cluster_size, height),
                col1=min(left + cluster_size, width),
            )
            clusters.append(cluster)
            index[(br, bc)] = cluster
            cid += 1
    return clusters, index


def _runs(values: list[int]) -> list[list[int]]:
    """Group sorted integers into runs of consecutive values."""
    runs: list[list[int]] = []
    current: list[int] = []
    for v in values:
        if current and v == current[-1] + 1:
            current.append(v)
        else:
            if current:
                runs.append(current)
            current = [v]
    if current:
        runs.append(current)
    return runs


def find_entrances(grid, clusters, index, cluster_size: int = 8) -> list[Entrance]:
    """Find border entrances between every pair of adjacent clusters.

    For each shared border, scan for contiguous runs of adjacent open-cell
    pairs and place one entrance at the midpoint of each run (classic HPA*).
    """
    n_block_rows = (len(grid) + cluster_size - 1) // cluster_size
    n_block_cols = (len(grid[0]) + cluster_size - 1) // cluster_size
    entrances: list[Entrance] = []

    for br in range(n_block_rows):
        for bc in range(n_block_cols):
            cluster = index[(br, bc)]

            # Horizontal neighbour (right side): vertical shared border.
            if bc + 1 < n_block_cols:
                right = index[(br, bc + 1)]
                border_col = right.col0
                transitions = [
                    r
                    for r in cluster.rows
                    if is_open(grid, r, border_col - 1) and is_open(grid, r, border_col)
                ]
                for run in _runs(transitions):
                    mid = run[len(run) // 2]
                    entrances.append(
                        Entrance(cluster, right, (mid, border_col - 1), (mid, border_col))
                    )

            # Vertical neighbour (below): horizontal shared border.
            if br + 1 < n_block_rows:
                below = index[(br + 1, bc)]
                border_row = below.row0
                transitions = [
                    c
                    for c in cluster.cols
                    if is_open(grid, border_row - 1, c)
                    and is_open(grid, border_row, c)
                ]
                for run in _runs(transitions):
                    mid = run[len(run) // 2]
                    entrances.append(
                        Entrance(cluster, below, (border_row - 1, mid), (border_row, mid))
                    )

    return entrances
