result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/hpa/query.py", "content": """"Answer point-to-point queries via abstract search + local refinement.

Pipeline:
  1. Attach start/goal to every border entrance of their own clusters using
     cluster-restricted BFS (exact distances and paths).
  2. Run Dijkstra on the small abstract graph.
  3. Stitch the concrete cell path from cached BFS segments.
If the abstract search fails (should not happen when start and goal are
connected), fall back to a plain grid-wide BFS so callers always get a valid,
optimal answer.
"""
from __future__ import annotations

import heapq
from math import inf

from .abstract_graph import AbstractGraph
from .grid import Cell, bfs, bfs_path, is_open, shortest_path


def find_hierarchical_path(
    graph: AbstractGraph, start: Cell, goal: Cell, allow_fallback: bool = True
) -> list[Cell] | None:
    """Return a concrete cell path from *start* to *goal* (inclusive)."""
    grid = graph.grid
    if not (is_open(grid, *start) and is_open(grid, *goal)):
        return None
    if start == goal:
        return [start]

    cs = graph.cluster_containing(start)
    cg = graph.cluster_containing(goal)
    if cs is None or cg is None:
        return None

    if cs.id != cg.id:
        path = _abstract_search(graph, start, goal, cs, cg)
        if path is not None:
            return path

    if allow_fallback:
        return shortest_path(grid, start, goal)
    return None


# ---------------------------------------------------------------------- #
def _attach(graph: AbstractGraph, source: Cell):
    """BFS within the source's cluster to all of its entrance nodes.

    Returns ``(dist, path)`` dicts for reachable entrance nodes.
    """
    cluster = graph.cluster_containing(source)
    dist_all, parent = bfs(graph.grid, source, region=cluster.contains)
    dist: dict[Cell, float] = {}
    paths: dict[Cell, list[Cell]] = {}
    for node in graph.nodes_in_cluster(cluster.id):
        if node in dist_all:
            dist[node] = dist_all[node]
            paths[node] = bfs_path(parent, source, node)
    return dist, paths


def _abstract_search(graph, start, goal, cs, cg) -> list[Cell] | None:
    dist_s, path_s = _attach(graph, start)
    dist_g, path_g = _attach(graph, goal)
    if not dist_s or not dist_g:
        return None

    def successors(u: Cell):
        """Directed abstract neighbours of abstract-node *u*."""
        out: list[tuple[Cell, float]] = []
        if u == start:
            out.extend((node, d) for node, d in dist_s.items())
        cid = graph.node_cluster.get(u)
        if cid is not None:
            out.extend(graph.adjacency[u])
            if cid == cg.id and u in dist_g:
                out.append((goal, dist_g[u]))
        return out

    # Dijkstra over {entrance nodes} U {start, goal}.
    dist = {start: 0}
    prev: dict[Cell, Cell] = {}
    settled: set[Cell] = set()
    pq: list[tuple[float, Cell]] = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if u in settled:
            continue
        settled.add(u)
        if u == goal:
            break
        for v, w in successors(u):
            nd = d + w
            if nd < dist.get(v, inf):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(pq, (nd, v))

    if goal not in settled:
        return None

    chain = [goal]
    while chain[-1] != start:
        chain.append(prev[chain[-1]])
    chain.reverse()

    return _stitch(graph, chain, start, goal, path_s, path_g)


def _stitch(graph, chain, start, goal, path_s, path_g) -> list[Cell]:
    """Concatenate concrete segments along the abstract node chain."""
    segments: list[list[Cell]] = []
    for a, b in zip(chain, chain[1:]):
        if a == start and b in path_s:
            segments.append(path_s[b])                      # start -> entrance
        elif b == goal and a in path_g:
            segments.append(path_g[a][::-1])                # entrance -> goal
        else:
            if abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1:
                segments.append([a, b])                     # inter-cluster step
            else:
                segments.append(graph.local_path(a, b))     # intra-cluster BFS

    full = list(segments[0])
    for seg in segments[1:]:
        full.extend(seg[1:])                                # skip duplicate joint
    return full
